import type * as React from "react"
import { cn } from "cn"

import { buttonVariants } from "@/components/ui/button"

type NativeActionProps =
  | ({ href: string } & Omit<React.ComponentProps<"a">, "href">)
  | ({ href?: undefined } & React.ComponentProps<"button">)

/**
 * Plain HTML action (engine:none): an <a> when href is set, otherwise a
 * <button>, styled with the aria-nova button recipe (appearance.primary,
 * size.md). For static or no-JS surfaces where a React Aria Button cannot
 * hydrate; hover, pressed, focus-visible and disabled are native CSS states.
 */
function NativeAction({ className, ...props }: NativeActionProps) {
  const classes = cn(buttonVariants({ variant: "default", size: "lg" }), className)
  if (props.href !== undefined) {
    return <a data-slot="native-action" className={classes} {...(props as React.ComponentProps<"a">)} />
  }
  const { type = "button", ...rest } = props as React.ComponentProps<"button">
  return <button data-slot="native-action" type={type} className={classes} {...rest} />
}

export { NativeAction }
